func(k, old, new string, d *schema.ResourceData) bool {
	localMd5Hash := ""
	if config_bundle, ok := d.GetOkExists("config_bundle"); ok {
		localMd5Hash = tpgresource.GetFileMd5Hash(config_bundle.(string))
	}
	if localMd5Hash == "" {
		return false
	}

	if old != localMd5Hash {
		return false
	}

	return true
}

