func(k, old, new string, d *schema.ResourceData) bool {
	_, n := d.GetChange(strings.TrimSuffix(k, ".#"))
	if !strings.HasSuffix(k, ".#") {
		return false
	}
	var l []interface{}
	if new == "1" && old == "0" {
		l = n.([]interface{})
		contents, ok := l[0].(map[string]interface{})
		if !ok {
			return false
		}
		if contents["enabled"] == false {
			return true
		}
	}
	if new == "0" && old == "1" {
		n := d.Get(strings.TrimSuffix(k, ".#"))
		l = n.([]interface{})
		contents := l[0].(map[string]interface{})
		if contents["enabled"] == false {
			return true
		}
	}
	return false
}

func(k, old, new string, d *schema.ResourceData) bool {
	if k == "ip_filter.#" {
		o, _ := d.GetChange("ip_filter")
		l := o.([]interface{})
		if len(l) == 0 {
			return false
		}

		if contents, ok := l[0].(map[string]interface{}); !ok {
			return false
		} else if mode, ok := contents["mode"].(string); ok && mode == "Disabled" {
			return true
		}
		return false
	} else if k == "ip_filter.0.mode" {
		return old == "Disabled" && new == ""
	}
	return false
}

func(k, old, new string, d *schema.ResourceData) bool {
	return old != "" && new == ""
}

